package main
import ("context"; "flag"; "fmt"; "os"; "os/signal"; "time"; "spike/core")
func main() { path:=flag.String("cookies","cookies.json","cookie JSON file"); platform:=flag.String("platform","messenger","messenger or facebook"); dir:=flag.String("data","./spike-data","data directory"); duration:=flag.Duration("duration",5*time.Minute,"run duration"); flag.Parse(); if err:=run(*path,*platform,*dir,*duration); err!=nil {fmt.Fprintln(os.Stderr,"error:",err); os.Exit(1)} }
func run(path,platform,dir string,d time.Duration) error { b,err:=os.ReadFile(path); if err!=nil{return fmt.Errorf("read cookies %q: %w",path,err)}; c,err:=core.ParseCookies(b,platform); if err!=nil{return err}; ctx,stop:=signal.NotifyContext(context.Background(),os.Interrupt); defer stop(); ctx,cancel:=context.WithTimeout(ctx,d); defer cancel(); return core.Run(ctx,c,dir,func(e core.Event){if e["type"]=="message" {fmt.Printf("%v thread=%v e2ee=%v sender=%v text=%v\n",e["time"],e["thread_id"],e["e2ee"],e["sender"],e["text"])} else {fmt.Printf("%v\n",e)}}) }
